import std/string (join)

func setField(fields: [{key: string, value: Json}], k: string, v: Json) -> [{key: string, value: Json}] =
  map(\f. if f.key == k then {key: k, value: v} else f, fields)

func render(j: Json) -> string =
  match j {
    JObject(fields) => {
      let parts = map(\f. "${encode(js(f.key))}: ${render(f.value)}", fields);
      "{${join(", ", parts)}}"
    },
    JArray(items) => "[${join(", ", map(render, items))}]",
    _ => encode(j)
  }

export func main() -> () ! {IO} {
  let src = "{\"name\": \"alice\", \"age\": 30, \"role\": \"engineer\"}";
  match decode(src) {
    Ok(JObject(fields)) => {
      let f1 = setField(fields, "age", jint(31));
      let f2 = setField(f1, "role", js("senior engineer"));
      println(render(JObject(f2)))
    },
    Ok(_) => println("not an object"),
    Err(e) => println(e)
  }
}
